-- Kopje Store schema 0087: hashtag keys as fixed points. Never edit after release (checksummed).
--
-- A hashtag's key (status_tags, tag_follows, featured_tags, trend_tags and tag_trend_reviews name it) is now
-- normalizeTag (src/domain/tag-name.ts): Mastodon's HashtagNormalizer#normalize applied twice, so that normalizing a
-- key gives the key back. The single pass was not a fixed point where a character it drops, or marks it sorts, leave
-- two characters that compose: U+1100 U+0301 U+1161 was stored as U+1100 U+1161, which every lookup now names U+AC00.
-- Every character a pass leaves is eligible (one normalizeOnce keeps as it is), and on a name of eligible characters
-- the second pass is NFC (test-node/tag-key-fixed-points.test.ts), so each stored key is renamed to its NFC here, and
-- the rows that meet under one name are merged.
--
-- The lookup tables are the runtime's Unicode 17, their literals as `node scripts/tag-key-literals.mjs` prints them
-- from Node's ICU (test-node/tag-key-fixed-points.test.ts runs it and compares, test/tag-key-tables.test.ts compares
-- workerd's): tag_key_chars, the eligible code points;
-- tag_key_triggers, the eligible ones NFC can change a name at (a nonstarter, or one whose first piece is the second
-- of a composite; a name without one is NFC already); tag_nfc_pieces, the canonical decomposition of each eligible
-- character that has one, Hangul syllables left out; tag_nfc_ccc, the rank of each nonstarter's combining class;
-- tag_nfc_pairs, the primary composites, Hangul's L + V and LV + T added below.
--
-- A name is repaired when it is TEXT holding a character other than 0-9, _ and a-z, at most 300,000 bytes, without
-- NUL, and at most 150,000 code points (judged in that order): the longest key a writer stored, a status's hashtag of
-- MAX_RAW_LENGTH code units each expanding to at most 15 code points and 30 bytes (test/migrations.test.ts derives both
-- from the writers' bounds). It is renamed only when it is well-formed UTF-8, every character is eligible, and one is
-- a trigger. Any other name, a converted or imported one, stays as stored: lookups, which normalize, do not reach it,
-- and lists show it by its bytes as before (src/domain/tag-bounds.ts listedTagName).
--
-- Merges, with nothing sent (as in 0019_tag_normalization: a Remove of a merged featured hashtag could take away the
-- only one a follower holds for the name; a Mastodon follower may keep one extra):
-- - status_tags keeps one row per status and name, its public the status's.
-- - tag_follows and featured_tags keep, for each account and new name, the lowest id among the rows of the old names
--   and of the new one, with its display_name.
-- - trend_tags keeps one row per new name: the highest score, and the highest peak with its time (the later time
--   between equal peaks). tag_trend_reviews keeps the newest decision, and between equal times not trendable. A new
--   name past the table's name CHECK keeps its rows as they were.
-- - The local accounts' featured hashtags under each new name are counted again from status_tags, as featuring one
--   counts them (src/domain/featured-tags.ts); a remote account's are counted when read.
--
-- Cost: the file creates work tables, so it is not declared foreignKeys: 'unchanged' and the upgrade checks every
-- reference of the Store (workerd refuses TEMP tables). Each table's names are read once to find the names with
-- another character (status_tags through status_tags_name, each row; the others whole); each such name's bytes are
-- cut into chunks of 512 and walked, with a range lookup per character in the fixed-size tables, sorted, and composed
-- with a key lookup per piece. Then each renamed name's status_tags rows are read through status_tags_name, renamed
-- or deleted by their key, and status_tags_name and status_tags_public are built again (each reads every status_tags
-- row once and sorts it); tag_follows and featured_tags are read once more for their rows under a renamed name, and
-- each account's row of the new name is looked up by its key; trend_tags and tag_trend_reviews (capped) are read
-- whole. The recount reads the local accounts' featured hashtags through featured_tags_account_id, each new name
-- among them once through status_tags_name, and each of its statuses by key. A name of n bytes copies O(n^2 / 1024)
-- bytes while it is cut (about 88 MB at the bound). A seek compares with every key on its way and reads one that
-- overflows a page whole, so no seek here goes through an index that holds such names where it can be avoided:
-- tag_renames is looked up by the first 64 characters of a name (tag_renames_k), the moved status_tags rows by their
-- key and the rename's id, and the name indexes are rebuilt rather than updated a row at a time (renaming 50,000 rows
-- next to a name of 300,000 bytes took about 7 s through status_tags_name, against 1.7 s for both rebuilds).
-- Measured on the benchmark store of test/bench/migration-cost.ts (1,000,000 accounts, 2,000,000 statuses, and its
-- 20,000 hashtag names on 200,000 status_tags rows, one at the input bound and one past it, 100,000 rows of one
-- renamed key featured by every local account and 50,000 remote ones, trend_tags and tag_trend_reviews at their
-- caps) in workerd's local Durable Object SQLite, the whole Store's foreign keys verified: 11,171 and 11,192 ms in
-- two runs for the upgrade of this file through the kernel (its statements about 4.3 s of it, the foreign key check
-- about 6 s), within the budget of 20 s, at a load average of about 2.

CREATE TABLE tag_key_chars (first INTEGER PRIMARY KEY, last INTEGER NOT NULL);

CREATE TABLE tag_key_triggers (first INTEGER PRIMARY KEY, last INTEGER NOT NULL);

CREATE TABLE tag_nfc_pieces (ch INTEGER NOT NULL, j INTEGER NOT NULL, piece INTEGER NOT NULL, PRIMARY KEY (ch, j))
WITHOUT ROWID;

CREATE TABLE tag_nfc_ccc (ch INTEGER PRIMARY KEY, rank INTEGER NOT NULL);

CREATE TABLE tag_nfc_pairs (first INTEGER NOT NULL, second INTEGER NOT NULL, composite INTEGER NOT NULL,
  PRIMARY KEY (first, second)) WITHOUT ROWID;






-- Hangul's L + V and LV + T, as pairs.
WITH RECURSIVE l(v) AS (SELECT 0 UNION ALL SELECT v + 1 FROM l WHERE v < 18),
  m(v) AS (SELECT 0 UNION ALL SELECT v + 1 FROM m WHERE v < 20),
  t(v) AS (SELECT 1 UNION ALL SELECT v + 1 FROM t WHERE v < 27)
SELECT 0x1100 + l.v, 0x1161 + m.v, 0xAC00 + (l.v * 21 + m.v) * 28 FROM l, m
UNION ALL
SELECT 0xAC00 + (l.v * 21 + m.v) * 28, 0x11A7 + t.v, 0xAC00 + (l.v * 21 + m.v) * 28 + t.v FROM l, m, t;

CREATE TABLE tag_renames (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, new_name TEXT, k TEXT);

INSERT OR IGNORE INTO tag_renames (name)
SELECT DISTINCT name FROM status_tags INDEXED BY status_tags_name
WHERE name GLOB '*[^0-9_a-z]*' AND typeof(name) = 'text' AND CASE WHEN length(CAST(name AS BLOB)) <= 300000
  THEN CASE WHEN instr(CAST(name AS BLOB), x'00') = 0 THEN length(name) <= 150000 END END;

INSERT OR IGNORE INTO tag_renames (name)
SELECT name FROM tag_follows
WHERE name GLOB '*[^0-9_a-z]*' AND typeof(name) = 'text' AND CASE WHEN length(CAST(name AS BLOB)) <= 300000
  THEN CASE WHEN instr(CAST(name AS BLOB), x'00') = 0 THEN length(name) <= 150000 END END;

INSERT OR IGNORE INTO tag_renames (name)
SELECT name FROM featured_tags
WHERE name GLOB '*[^0-9_a-z]*' AND typeof(name) = 'text' AND CASE WHEN length(CAST(name AS BLOB)) <= 300000
  THEN CASE WHEN instr(CAST(name AS BLOB), x'00') = 0 THEN length(name) <= 150000 END END;

INSERT OR IGNORE INTO tag_renames (name)
SELECT name FROM trend_tags
WHERE name GLOB '*[^0-9_a-z]*' AND typeof(name) = 'text' AND CASE WHEN length(CAST(name AS BLOB)) <= 300000
  THEN CASE WHEN instr(CAST(name AS BLOB), x'00') = 0 THEN length(name) <= 150000 END END;

INSERT OR IGNORE INTO tag_renames (name)
SELECT name FROM tag_trend_reviews
WHERE name GLOB '*[^0-9_a-z]*' AND typeof(name) = 'text' AND CASE WHEN length(CAST(name AS BLOB)) <= 300000
  THEN CASE WHEN instr(CAST(name AS BLOB), x'00') = 0 THEN length(name) <= 150000 END END;

-- Each name's bytes in chunks of at most 512 that end before a lead byte (a well-formed name splits between its
-- characters), then each chunk's code points: at each position the one starting there, the next position past its
-- UTF-8 length. A malformed name splits and walks somewhere; the check after refuses it.
CREATE TABLE tag_key_chunks (id INTEGER NOT NULL, k INTEGER NOT NULL, chunk BLOB NOT NULL, PRIMARY KEY (id, k))
WITHOUT ROWID;

WITH RECURSIVE peel(id, k, chunk, rest) AS (
  SELECT id, 0, NULL, CAST(name AS BLOB) FROM tag_renames
  UNION ALL
  SELECT id, k + 1,
    substr(rest, 1, CASE WHEN length(rest) <= 512 THEN length(rest)
      WHEN hex(substr(rest, 513, 1)) NOT BETWEEN '80' AND 'BF' THEN 512
      WHEN hex(substr(rest, 512, 1)) NOT BETWEEN '80' AND 'BF' THEN 511
      WHEN hex(substr(rest, 511, 1)) NOT BETWEEN '80' AND 'BF' THEN 510 ELSE 509 END),
    substr(rest, 1 + CASE WHEN length(rest) <= 512 THEN length(rest)
      WHEN hex(substr(rest, 513, 1)) NOT BETWEEN '80' AND 'BF' THEN 512
      WHEN hex(substr(rest, 512, 1)) NOT BETWEEN '80' AND 'BF' THEN 511
      WHEN hex(substr(rest, 511, 1)) NOT BETWEEN '80' AND 'BF' THEN 510 ELSE 509 END)
  FROM peel WHERE length(rest) > 0)
SELECT id, k, chunk FROM peel WHERE k > 0;

CREATE TABLE tag_key_walk (id INTEGER NOT NULL, k INTEGER NOT NULL, p INTEGER NOT NULL, cp INTEGER NOT NULL,
  PRIMARY KEY (id, k, p)) WITHOUT ROWID;

WITH RECURSIVE walk(id, k, chunk, p, cp) AS (
  SELECT id, k, chunk, 1, unicode(CAST(substr(chunk, 1, 4) AS TEXT)) FROM tag_key_chunks
  UNION ALL
  SELECT id, k, chunk, p + CASE WHEN cp < 0x80 THEN 1 WHEN cp < 0x800 THEN 2 WHEN cp < 0x10000 THEN 3 ELSE 4 END,
    unicode(CAST(substr(chunk,
      p + CASE WHEN cp < 0x80 THEN 1 WHEN cp < 0x800 THEN 2 WHEN cp < 0x10000 THEN 3 ELSE 4 END, 4) AS TEXT))
  FROM walk
  WHERE p + CASE WHEN cp < 0x80 THEN 1 WHEN cp < 0x800 THEN 2 WHEN cp < 0x10000 THEN 3 ELSE 4 END <= length(chunk))
SELECT id, k, p, coalesce(cp, -1) FROM walk;

DROP TABLE tag_key_chunks;

-- Kept only when every code point is eligible, the code points written out again are the name's bytes (so it is
-- well-formed UTF-8), and one of them is a trigger.
DELETE FROM tag_renames WHERE id IN (
  SELECT w.id FROM tag_key_walk w GROUP BY w.id
  HAVING NOT (min(coalesce((SELECT c.last FROM tag_key_chars c WHERE c.first <= w.cp ORDER BY c.first DESC LIMIT 1)
      >= w.cp, 0)) = 1
    AND max(coalesce((SELECT t.last FROM tag_key_triggers t WHERE t.first <= w.cp ORDER BY t.first DESC LIMIT 1)
      >= w.cp, 0)) = 1
    AND CAST(group_concat(char(w.cp), '' ORDER BY w.k, w.p) AS BLOB)
      = (SELECT CAST(r.name AS BLOB) FROM tag_renames r WHERE r.id = w.id)));

-- NFC: each code point's pieces (a Hangul syllable is one), numbered in runs (s counts the starters up to the piece)
-- and sorted stably by class within each; then composed left to right onto the last starter x. A piece is absorbed
-- when it composes with x and nothing is left unabsorbed (b = 0), or it is a nonstarter of a class above the last
-- left (b); absorbing leaves b. Otherwise a starter outputs x and becomes x, and a nonstarter is left. Each output is a
-- row t sorted by (g, o): x at (its starter's n, 0), a piece left at (x's n, its own n), a nonstarter before any
-- starter at (its n, 0). A last piece -1 for each name, a starter that composes with nothing, outputs the last x.
CREATE TABLE tag_nfc_queue (id INTEGER NOT NULL, n INTEGER NOT NULL, piece INTEGER NOT NULL, rank INTEGER NOT NULL,
  PRIMARY KEY (id, n)) WITHOUT ROWID;

SELECT id, row_number() OVER (PARTITION BY id ORDER BY s, rank, k, p, j), piece, rank
FROM (SELECT id, k, p, j, piece, rank,
    sum(rank = 0) OVER (PARTITION BY id ORDER BY k, p, j ROWS UNBOUNDED PRECEDING) AS s
  FROM (SELECT w.id, w.k, w.p, coalesce(d.j, 0) AS j, coalesce(d.piece, w.cp) AS piece,
      coalesce((SELECT c.rank FROM tag_nfc_ccc c WHERE c.ch = coalesce(d.piece, w.cp)), 0) AS rank
    FROM tag_renames r CROSS JOIN tag_key_walk w ON w.id = r.id LEFT JOIN tag_nfc_pieces d ON d.ch = w.cp));


DROP TABLE tag_key_walk;

CREATE TABLE tag_nfc_out (id INTEGER NOT NULL, g INTEGER NOT NULL, o INTEGER NOT NULL, t TEXT NOT NULL,
  PRIMARY KEY (id, g, o)) WITHOUT ROWID;

WITH RECURSIVE nfc(id, n, x, xn, b, t, g, o) AS (
  SELECT id, 0, NULL, 0, 0, NULL, 0, 0 FROM tag_renames
  UNION ALL
  SELECT q.id, q.n,
    CASE WHEN c.composite IS NOT NULL AND (nfc.b = 0 OR (q.rank > 0 AND nfc.b < q.rank)) THEN c.composite
      WHEN q.rank = 0 THEN q.piece ELSE nfc.x END,
    CASE WHEN c.composite IS NOT NULL AND (nfc.b = 0 OR (q.rank > 0 AND nfc.b < q.rank)) THEN nfc.xn
      WHEN q.rank = 0 THEN q.n ELSE nfc.xn END,
    CASE WHEN c.composite IS NOT NULL AND (nfc.b = 0 OR (q.rank > 0 AND nfc.b < q.rank)) THEN nfc.b
      WHEN q.rank = 0 OR nfc.x IS NULL THEN 0 ELSE q.rank END,
    CASE WHEN c.composite IS NOT NULL AND (nfc.b = 0 OR (q.rank > 0 AND nfc.b < q.rank)) THEN NULL
      WHEN q.rank > 0 THEN char(q.piece) WHEN nfc.x IS NOT NULL THEN char(nfc.x) END,
    CASE WHEN nfc.x IS NULL THEN q.n ELSE nfc.xn END,
    CASE WHEN nfc.x IS NULL OR q.rank = 0 THEN 0 ELSE q.n END
  FROM nfc JOIN tag_nfc_queue q ON q.id = nfc.id AND q.n = nfc.n + 1
    LEFT JOIN tag_nfc_pairs c ON c.first = nfc.x AND c.second = q.piece)
SELECT id, g, o, t FROM nfc WHERE t IS NOT NULL;

DROP TABLE tag_nfc_queue;

UPDATE tag_renames SET new_name = (SELECT group_concat(o.t, '' ORDER BY o.g, o.o) FROM tag_nfc_out o
  WHERE o.id = tag_renames.id);

DROP TABLE tag_nfc_out;

DELETE FROM tag_renames WHERE new_name IS NULL OR new_name = name;

CREATE INDEX tag_renames_new_name ON tag_renames (new_name);

-- A name's first 64 characters: lookups by name seek this key, then compare the whole name, so that a seek never
-- compares with a long name that overflows a page (which reads it whole).
UPDATE tag_renames SET k = substr(name, 1, 64);

CREATE INDEX tag_renames_k ON tag_renames (k);

-- status_tags: one row per status and name, its public the status's. The rows under an old name are read through
-- status_tags_name; then its two name indexes go while each row is renamed where it stands by its key (unless its
-- status already holds the new name; the rows left under an old name are such duplicates and go), and are built again
-- as 0000_initial and 0004_status_tags_public made them. A seek of status_tags_name compares with every key on its
-- way, read whole when it overflows a page, so a renamed row next to a long name cost a read of that name per seek
-- (a 300,000-byte one: 50,000 renamed rows took seconds); the rebuild sorts the rows once instead.
CREATE TABLE tag_status_moves (status_id TEXT NOT NULL, id INTEGER NOT NULL, PRIMARY KEY (status_id, id))
WITHOUT ROWID;

SELECT t.status_id, r.id FROM tag_renames r CROSS JOIN status_tags t INDEXED BY status_tags_name ON t.name = r.name;

DROP INDEX status_tags_public;

DROP INDEX status_tags_name;

UPDATE OR IGNORE status_tags
SET name = (SELECT r.new_name FROM tag_status_moves m CROSS JOIN tag_renames r ON r.id = m.id
  WHERE m.status_id = status_tags.status_id AND r.name = status_tags.name)
WHERE status_id IN (SELECT status_id FROM tag_status_moves) AND EXISTS (SELECT 1 FROM tag_status_moves m
  CROSS JOIN tag_renames r ON r.id = m.id WHERE m.status_id = status_tags.status_id AND r.name = status_tags.name);

DELETE FROM status_tags WHERE status_id IN (SELECT status_id FROM tag_status_moves) AND EXISTS (SELECT 1
  FROM tag_status_moves m CROSS JOIN tag_renames r ON r.id = m.id
  WHERE m.status_id = status_tags.status_id AND r.name = status_tags.name);

DROP TABLE tag_status_moves;

CREATE INDEX status_tags_name ON status_tags (name, status_id);

CREATE INDEX status_tags_public ON status_tags (name, status_id) WHERE public = 1;

-- tag_follows and featured_tags: the rows under an old name, read in one pass, with their new name; of each account
-- and new name, the lowest id among them and the account's row of the new name is kept, the others go, and the kept
-- one is renamed, so (account_id, name) stays unique.
CREATE TABLE tag_moves (id NOT NULL PRIMARY KEY, account_id TEXT NOT NULL, name TEXT NOT NULL) WITHOUT ROWID;

CREATE INDEX tag_moves_name ON tag_moves (account_id, name);

CREATE TABLE tag_keeps (account_id TEXT NOT NULL, name TEXT NOT NULL, id NOT NULL, PRIMARY KEY (account_id, name))
WITHOUT ROWID;

SELECT f.id, f.account_id, r.new_name FROM tag_follows f CROSS JOIN tag_renames r INDEXED BY tag_renames_k
  ON r.k = substr(f.name, 1, 64) AND r.name = f.name
WHERE f.name GLOB '*[^0-9_a-z]*';

SELECT account_id, name, min(id) FROM (
  SELECT account_id, name, id FROM tag_moves
  UNION ALL
  SELECT g.account_id, g.name, g.id FROM (SELECT DISTINCT account_id, name FROM tag_moves) m
    CROSS JOIN tag_follows g ON g.account_id = m.account_id AND g.name = m.name)
GROUP BY account_id, name;

DELETE FROM tag_follows WHERE id IN (
  SELECT m.id FROM tag_moves m CROSS JOIN tag_keeps k ON k.account_id = m.account_id AND k.name = m.name
  WHERE m.id <> k.id
  UNION ALL
  SELECT g.id FROM tag_keeps k CROSS JOIN tag_follows g ON g.account_id = k.account_id AND g.name = k.name
  WHERE g.id <> k.id);

UPDATE tag_follows SET name = (SELECT m.name FROM tag_moves m WHERE m.id = tag_follows.id)
WHERE id IN (SELECT id FROM tag_moves);

DELETE FROM tag_moves;

DELETE FROM tag_keeps;

SELECT f.id, f.account_id, r.new_name FROM featured_tags f CROSS JOIN tag_renames r INDEXED BY tag_renames_k
  ON r.k = substr(f.name, 1, 64) AND r.name = f.name
WHERE f.name GLOB '*[^0-9_a-z]*';

SELECT account_id, name, min(id) FROM (
  SELECT account_id, name, id FROM tag_moves
  UNION ALL
  SELECT g.account_id, g.name, g.id FROM (SELECT DISTINCT account_id, name FROM tag_moves) m
    CROSS JOIN featured_tags g ON g.account_id = m.account_id AND g.name = m.name)
GROUP BY account_id, name;

DELETE FROM featured_tags WHERE id IN (
  SELECT m.id FROM tag_moves m CROSS JOIN tag_keeps k ON k.account_id = m.account_id AND k.name = m.name
  WHERE m.id <> k.id
  UNION ALL
  SELECT g.id FROM tag_keeps k CROSS JOIN featured_tags g ON g.account_id = k.account_id AND g.name = k.name
  WHERE g.id <> k.id);

UPDATE featured_tags SET name = (SELECT m.name FROM tag_moves m WHERE m.id = featured_tags.id)
WHERE id IN (SELECT id FROM tag_moves);

DROP TABLE tag_keeps;

DROP TABLE tag_moves;


-- trend_tags and tag_trend_reviews: one row for each new name that passes the table's name CHECK, made of its rows
-- under the old names and its own; they all go before the new rows go in, so neither cap's trigger fires. A name that
-- would fail it keeps its rows as they are.
CREATE TABLE tag_trend_moves (name TEXT NOT NULL PRIMARY KEY, score REAL NOT NULL, max_score REAL NOT NULL,
  max_score_at TEXT NOT NULL) WITHOUT ROWID;

SELECT name, top, max_score, max_score_at FROM (
  SELECT name, max(score) OVER (PARTITION BY name) AS top, max_score, max_score_at,
    row_number() OVER (PARTITION BY name ORDER BY max_score DESC, max_score_at DESC) AS place
  FROM (SELECT r.new_name AS name, t.score, t.max_score, t.max_score_at
      FROM trend_tags t CROSS JOIN tag_renames r INDEXED BY tag_renames_k
        ON r.k = substr(t.name, 1, 64) AND r.name = t.name
    UNION ALL
    SELECT t.name, t.score, t.max_score, t.max_score_at
      FROM trend_tags o CROSS JOIN tag_renames r INDEXED BY tag_renames_k
        ON r.k = substr(o.name, 1, 64) AND r.name = o.name CROSS JOIN trend_tags t ON t.name = r.new_name))
WHERE place = 1 AND typeof(name) = 'text' AND length(CAST(name AS BLOB)) BETWEEN 1 AND 1024
    AND instr(CAST(name AS BLOB), x'00') = 0 AND length(name) <= 256
    AND name NOT GLOB ('*[' || char(1) || '-/:-^`{-' || char(127) || ']*');

DELETE FROM trend_tags WHERE name IN (SELECT name FROM tag_trend_moves)
  OR name IN (SELECT r.name FROM tag_trend_moves m CROSS JOIN tag_renames r INDEXED BY tag_renames_new_name
    ON r.new_name = m.name);

SELECT name, score, max_score, max_score_at FROM tag_trend_moves;

DROP TABLE tag_trend_moves;

CREATE TABLE tag_review_moves (name TEXT NOT NULL PRIMARY KEY, trendable INTEGER NOT NULL, reviewed_at TEXT NOT NULL)
WITHOUT ROWID;

SELECT name, trendable, reviewed_at FROM (
  SELECT name, trendable, reviewed_at,
    row_number() OVER (PARTITION BY name ORDER BY reviewed_at DESC, trendable) AS place
  FROM (SELECT r.new_name AS name, t.trendable, t.reviewed_at
      FROM tag_trend_reviews t CROSS JOIN tag_renames r INDEXED BY tag_renames_k
        ON r.k = substr(t.name, 1, 64) AND r.name = t.name
    UNION ALL
    SELECT t.name, t.trendable, t.reviewed_at
      FROM tag_trend_reviews o CROSS JOIN tag_renames r INDEXED BY tag_renames_k
        ON r.k = substr(o.name, 1, 64) AND r.name = o.name
      CROSS JOIN tag_trend_reviews t ON t.name = r.new_name))
WHERE place = 1 AND typeof(name) = 'text' AND length(CAST(name AS BLOB)) BETWEEN 1 AND 1024
    AND instr(CAST(name AS BLOB), x'00') = 0 AND length(name) <= 256
    AND name NOT GLOB ('*[' || char(1) || '-/:-^`{-' || char(127) || ']*');

DELETE FROM tag_trend_reviews WHERE name IN (SELECT name FROM tag_review_moves)
  OR name IN (SELECT r.name FROM tag_review_moves m CROSS JOIN tag_renames r INDEXED BY tag_renames_new_name
    ON r.new_name = m.name);

SELECT name, trendable, reviewed_at FROM tag_review_moves;

DROP TABLE tag_review_moves;

-- The local accounts' featured hashtags under each new name, counted again as featuring one counts them
-- (src/domain/featured-tags.ts): the account's public and unlisted originals with the hashtag, and the publication
-- time of the newest by id. The local accounts' featured hashtags are read through featured_tags_account_id; each new
-- name among them is read once through status_tags_name, each of its statuses by key; then each such featured hashtag
-- is set, at 0 without a status.
CREATE TABLE tag_featured_rows (account_id TEXT NOT NULL, name TEXT NOT NULL, id TEXT NOT NULL,
  PRIMARY KEY (account_id, name)) WITHOUT ROWID;

SELECT f.account_id, f.name, f.id
FROM local_accounts l CROSS JOIN featured_tags f INDEXED BY featured_tags_account_id ON f.account_id = l.account_id
WHERE f.name IN (SELECT new_name FROM tag_renames);

CREATE TABLE tag_featured_counts (name TEXT NOT NULL, account_id TEXT NOT NULL, n INTEGER NOT NULL,
  last_id TEXT NOT NULL, PRIMARY KEY (name, account_id)) WITHOUT ROWID;

SELECT k.name, s.account_id, count(*), max(s.id)
FROM (SELECT DISTINCT name FROM tag_featured_rows) k
  CROSS JOIN status_tags t INDEXED BY status_tags_name ON t.name = k.name
  CROSS JOIN statuses s INDEXED BY sqlite_autoindex_statuses_1 ON s.id = t.status_id
WHERE s.reblog_of_id IS NULL AND s.visibility IN ('public', 'unlisted')
  AND EXISTS (SELECT 1 FROM tag_featured_rows r WHERE r.account_id = s.account_id AND r.name = k.name)
GROUP BY k.name, s.account_id;

UPDATE featured_tags SET (statuses_count, last_status_at) = (
  SELECT coalesce(c.n, 0), (SELECT s.published_at FROM statuses s WHERE s.id = c.last_id)
  FROM (SELECT 1) LEFT JOIN tag_featured_counts c
    ON c.name = featured_tags.name AND c.account_id = featured_tags.account_id)
WHERE id IN (SELECT id FROM tag_featured_rows);

DROP TABLE tag_featured_counts;

DROP TABLE tag_featured_rows;

DROP TABLE tag_renames;

DROP TABLE tag_key_chars;

DROP TABLE tag_key_triggers;

DROP TABLE tag_nfc_pieces;

DROP TABLE tag_nfc_ccc;

DROP TABLE tag_nfc_pairs;
